import{_ as t,o as r,c as a,a3 as d}from"./chunks/framework.C4dN0wKy.js";const u=JSON.parse('{"title":"Hyperliquid SDK runtime compatibility","description":"Live exchange REST and WebSocket checks for Hyperliquid across JavaScript runtimes.","frontmatter":{"title":"Hyperliquid SDK runtime compatibility","description":"Live exchange REST and WebSocket checks for Hyperliquid across JavaScript runtimes."},"headers":[],"relativePath":"compatibility.md","filePath":"compatibility.md"}'),i={name:"compatibility.md"};function s(o,e,n,c,h,p){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="runtime-compatibility" tabindex="-1">Runtime compatibility <a class="header-anchor" href="#runtime-compatibility" aria-label="Permalink to &quot;Runtime compatibility&quot;">​</a></h1><p>Set up the Hyperliquid SDK for Node.js, Bun, Deno, browsers and React Native. The setup instructions use the latest SDK release. The checks below exercise public REST requests and WebSocket subscriptions against the exchange.</p><table tabindex="0"><thead><tr><th>Environment</th><th>Tested version</th><th>Result</th></tr></thead><tbody><tr><td><a href="#node">Node.js</a></td><td>v24.19.0</td><td>Live checks passed</td></tr><tr><td><a href="#bun">Bun</a></td><td>1.4.4</td><td>Live checks passed</td></tr><tr><td><a href="#deno">Deno</a></td><td>deno 2.9.6 (stable, release, aarch64-apple-darwin)</td><td>Live checks passed</td></tr><tr><td><a href="#browser">Browser / default Vite</a></td><td>Chromium 156.0.0.0</td><td>Live checks passed</td></tr><tr><td><a href="#next">Next.js server</a></td><td>Next.js 16.4.5 / Node v24.19.0</td><td>Live checks passed</td></tr><tr><td><a href="#react-native">React Native / default Android</a></td><td>React Native 0.88.1 / Expo 58.0.23 / Android API 35 / Hermes</td><td>Live checks passed</td></tr><tr><td><a href="#react-native-ios">React Native / default iOS</a></td><td>React Native 0.88.1 / Expo 58.0.23</td><td>Build only</td></tr></tbody></table><p>Tested SDK: <code>@siebly/hyperliquid-api@1.0.1</code>. Last run: <strong>2026-11-04</strong> on <strong>darwin/arm64</strong>. Each environment lists its check date.</p><p>The SDK version shown is the version we tested, not a minimum requirement. Earlier SDK releases may also work.</p><h2 id="node" tabindex="-1">Node.js <a class="header-anchor" href="#node" aria-label="Permalink to &quot;Node.js {#node}&quot;">​</a></h2><p><strong>Live checks passed.</strong> The package checks listed below passed against the live exchange APIs.</p><p>Checked 2026-11-04.</p><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>ES module import</td><td>Passed</td></tr><tr><td>Live exchange REST price</td><td>Passed</td></tr><tr><td>Live exchange market-data subscription</td><td>Passed</td></tr><tr><td>Close WebSocket client</td><td>Passed</td></tr><tr><td>CommonJS import</td><td>Passed</td></tr><tr><td>TypeScript consumer</td><td>Passed</td></tr></tbody></table><p>Observed BTC price: <strong>78543.5</strong>, received 2026-11-04T11:05:06.569Z from <a href="https://api.hyperliquid.xyz/info" target="_blank" rel="noreferrer">https://api.hyperliquid.xyz/info</a>.</p><p>Observed BTC price: <strong>78551.5</strong>, received 2026-11-04T11:05:10.424Z from wss://api.hyperliquid.xyz/ws.</p><h2 id="bun" tabindex="-1">Bun <a class="header-anchor" href="#bun" aria-label="Permalink to &quot;Bun {#bun}&quot;">​</a></h2><p><strong>Live checks passed.</strong> The package checks listed below passed against the live exchange APIs.</p><p>Checked 2026-11-04.</p><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>ES module import</td><td>Passed</td></tr><tr><td>Live exchange REST price</td><td>Passed</td></tr><tr><td>Live exchange market-data subscription</td><td>Passed</td></tr><tr><td>Close WebSocket client</td><td>Passed</td></tr><tr><td>CommonJS import</td><td>Passed</td></tr><tr><td>TypeScript consumer</td><td>Passed</td></tr></tbody></table><p>Observed BTC price: <strong>78620.5</strong>, received 2026-11-04T11:12:31.099Z from <a href="https://api.hyperliquid.xyz/info" target="_blank" rel="noreferrer">https://api.hyperliquid.xyz/info</a>.</p><p>Observed BTC price: <strong>78615.5</strong>, received 2026-11-04T11:12:34.133Z from wss://api.hyperliquid.xyz/ws.</p><h2 id="deno" tabindex="-1">Deno <a class="header-anchor" href="#deno" aria-label="Permalink to &quot;Deno {#deno}&quot;">​</a></h2><p><strong>Live checks passed.</strong> The package checks listed below passed against the live exchange APIs.</p><p>Checked 2026-11-04.</p><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>ES module import</td><td>Passed</td></tr><tr><td>Live exchange REST price</td><td>Passed</td></tr><tr><td>Live exchange market-data subscription</td><td>Passed</td></tr><tr><td>Close WebSocket client</td><td>Passed</td></tr><tr><td>CommonJS import</td><td>Passed</td></tr><tr><td>TypeScript consumer</td><td>Passed</td></tr></tbody></table><p>Observed BTC price: <strong>78609.5</strong>, received 2026-11-04T11:12:38.616Z from <a href="https://api.hyperliquid.xyz/info" target="_blank" rel="noreferrer">https://api.hyperliquid.xyz/info</a>.</p><p>Observed BTC price: <strong>78610.5</strong>, received 2026-11-04T11:12:44.374Z from wss://api.hyperliquid.xyz/ws.</p><h2 id="browser" tabindex="-1">Browser / default Vite <a class="header-anchor" href="#browser" aria-label="Permalink to &quot;Browser / default Vite {#browser}&quot;">​</a></h2><p><strong>Live checks passed.</strong> The default Vite consumer received real exchange REST and WebSocket market data.</p><p>Checked 2026-11-04.</p><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>Production bundle</td><td>Passed</td></tr><tr><td>ES module import</td><td>Passed</td></tr><tr><td>Live exchange REST price</td><td>Passed</td></tr><tr><td>Live exchange market-data subscription</td><td>Passed</td></tr><tr><td>Close WebSocket client</td><td>Passed</td></tr></tbody></table><p>Observed BTC price: <strong>78568.5</strong>, received 2026-11-04T11:06:08.279Z from <a href="https://api.hyperliquid.xyz/info" target="_blank" rel="noreferrer">https://api.hyperliquid.xyz/info</a>.</p><p>Observed BTC price: <strong>78565.5</strong>, received 2026-11-04T11:06:10.683Z from wss://api.hyperliquid.xyz/ws.</p><p>Browser requests go directly to the exchange, without a local proxy. A failure can reflect browser CORS restrictions, exchange access restrictions, network conditions or an SDK issue; the observed error is retained above. Safari and Firefox have not been tested.</p><h2 id="next" tabindex="-1">Next.js server <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next.js server {#next}&quot;">​</a></h2><p><strong>Live checks passed.</strong> Production build and live exchange REST execution in a Node.js Route Handler passed. Client Components and the Edge runtime are not covered.</p><p>Checked 2026-11-04.</p><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>Production bundle</td><td>Passed</td></tr><tr><td>Server route execution</td><td>Passed</td></tr></tbody></table><p>The server route received BTC price <strong>78614.5</strong> at 2026-11-04T11:13:05.807Z.</p><p>The production Next.js server calls the actual exchange from a Node.js Route Handler. Client Components and Edge execution are not covered.</p><h2 id="react-native" tabindex="-1">React Native / default Android <a class="header-anchor" href="#react-native" aria-label="Permalink to &quot;React Native / default Android {#react-native}&quot;">​</a></h2><p><strong>Live checks passed.</strong> The SDK passed live exchange REST and WebSocket checks in Expo Go on the Android emulator. iOS, background suspension and custom native development builds are not covered.</p><p>Checked 2026-11-04.</p><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>Android Metro bundle</td><td>Passed</td></tr><tr><td>Native package import</td><td>Passed</td></tr><tr><td>Live exchange REST price</td><td>Passed</td></tr><tr><td>Live exchange market-data subscription</td><td>Passed</td></tr><tr><td>Close WebSocket client</td><td>Passed</td></tr></tbody></table><p>Observed BTC price: <strong>78565.5</strong>, received 2026-11-04T11:07:02.868Z from <a href="https://api.hyperliquid.xyz/info" target="_blank" rel="noreferrer">https://api.hyperliquid.xyz/info</a>.</p><p>Observed BTC price: <strong>78565.5</strong>, received 2026-11-04T11:07:06.374Z from wss://api.hyperliquid.xyz/ws.</p><p>The Android check builds with Metro, then runs direct exchange requests and subscriptions in Expo Go on an Android 15 ARM64 emulator with Hermes. A build failure prevents runtime verification. Background lifecycle and standalone release builds are not covered.</p><h2 id="react-native-ios" tabindex="-1">React Native / default iOS <a class="header-anchor" href="#react-native-ios" aria-label="Permalink to &quot;React Native / default iOS {#react-native-ios}&quot;">​</a></h2><p><strong>Build only.</strong> The iOS Metro bundle passed. No iOS simulator or device execution has been performed.</p><p>Checked 2026-11-04.</p><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>iOS Metro bundle</td><td>Passed</td></tr></tbody></table><p>iOS bundling is checked separately. No iOS simulator or device execution has been performed.</p><h2 id="scope-of-the-live-checks" tabindex="-1">Scope of the live checks <a class="header-anchor" href="#scope-of-the-live-checks" aria-label="Permalink to &quot;Scope of the live checks&quot;">​</a></h2><p>A passing runtime result requires importing the published SDK, receiving a positive BTC price from the real REST API, receiving a real market-data WebSocket update, and closing the client. Node.js, Bun and Deno also check CommonJS, TypeScript and natural process exit. No expected market price is hardcoded.</p><p>Checks make public market-data requests only. Authenticated requests, signing accepted by an exchange, order placement, rate-limit recovery, timeout handling, heartbeat recovery and reconnection are <strong>not verified</strong> by these checks. No credentials are supplied, no forced error responses are created and no exchange server is simulated.</p><p>Live results apply to the displayed package and runtime at the recorded check time, from this test machine’s network. Exchanges can restrict access by region, network or origin. A blocked connection is recorded as a failed live check rather than replaced with simulated data.</p><p><a href="/docs/hyperliquid/getting-started.html">Quickstart</a> · <a href="/docs/hyperliquid/guides/production.html">Production usage</a> · <a href="/docs/hyperliquid/guides/troubleshooting.html">Troubleshooting</a></p>',53)])])}const b=t(i,[["render",s]]);export{u as __pageData,b as default};
